-- ============================================================================
-- PARTIE 13 — Contenu du module 1 « Développement et attachement » (3 séquences)
-- Source : Projet pédagogique Koalakids (port d'attache, attachement sécure et
-- insécure, constellation d'attachement, doudou, arrivées et départs, rituels).
-- Les séquences RESTENT EN BROUILLON.
-- À exécuter en 7 temps : 13.1a, 13.1b, 13.2a, 13.2b, 13.3a, 13.3b, puis 13c.
-- Relançable : la trame est remplacée, les blocs ne sont ajoutés qu'une fois.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 13.1a Trame de la séquence 1/3 (Apport). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Un enfant qui se sent en sécurité peut s'aventurer. La base sûre vient avant l'exploration.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable d'expliquer pourquoi la sécurité affective vient avant l'exploration et de repérer si un enfant s'appuie déjà sur une base sûre ou cherche encore à se sécuriser.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Développement du jeune enfant et besoins affectifs"}, "duree_min": 45, "materiel": ["Fiche « Trois postures » (1 par personne)", "Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Présenter les 3 séances du module : apport, analyse d'une situation vécue, test d'une pratique.", "Chacun pense à un enfant qui s'éloigne facilement de l'adulte et à un enfant qui reste tout près, sans les nommer."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Un enfant qui se sent en sécurité peut s'aventurer : la base sûre vient avant l'exploration.", "idees": ["Port d'attache : l'enfant prend le risque d'explorer s'il sent l'adulte disponible et sait qu'il peut revenir à tout moment. Sans sécurité affective, toute son énergie va à la recherche de sécurisation et il n'est pas disponible pour jouer ; sans aventure possible, il ne peut pas explorer.", "Les enfants ne sont pas tous au même point : un attachement « sécure » permet de se sécuriser même en l'absence de l'adulte, un attachement « insécure » ne le permet pas encore. Savoir où en est chaque enfant permet d'adapter notre accompagnement.", "On sécurise en répondant aux signaux de l'enfant, de façon chaleureuse et régulière : le prendre dans les bras, le consoler, chercher à apaiser la cause de sa peine. Il comprend ainsi qu'il peut compter sur nous."], "support": "Projet pédagogique Koalakids, « De l'attachement à l'exploration »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir un enfant du site, sans le nommer. On analyse ce que fait l'adulte, pas ce qu'est l'enfant.", "questions": ["Que s'est-il passé ? (ce que l'enfant fait quand l'adulte s'éloigne, quand il revient)", "Quel besoin de l'enfant ? Se sécuriser, ou déjà s'aventurer ?", "Quelle posture : port d'attache d'abord ?", "Que faire autrement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : me rendre visible et accessible sur ma proposition de jeu, les yeux à hauteur des enfants.", "Exemple : faire savoir à chaque enfant qui revient vers moi que je suis là pour lui.", "Exemple : observer un enfant et noter comment il se sécurise."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 2/3 : analyse d'une situation vécue, avec la « constellation d'attachement » d'un enfant."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 1 % 1/3 %';
-- FIN 13.1a

-- ---------------------------------------------------------------------------
-- 13.1b Blocs de la séquence 1/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Une base sûre pour partir", "paragraphes": ["L'enfant qui explore, qui joue avec les autres, qui s'aventure loin de nous, **n'est pas un enfant qui n'a plus besoin de nous**. C'est souvent le contraire : c'est parce qu'il sent que nous sommes disponibles qu'il ose partir.", "Cette première séance pose un repère : avant de chercher à faire jouer, à faire explorer ou à faire patienter, on s'assure que l'enfant a une base sûre à laquelle revenir."]}$kk$),
  (1,'citation',$kk${"texte": "« En pleine mer, un bateau qui possède un port d'attache navigue, tandis qu'un bateau sans port d'attache dérive. »\nAndré Stern"}$kk$),
  (2,'retenir',$kk${"titre": "À retenir", "points": ["**La sécurité vient avant l'exploration :** un enfant insécurisé cherche d'abord à se sécuriser et n'est pas disponible pour jouer.", "**Chaque enfant est à un endroit différent :** « sécure » ou « insécure », on observe pour adapter notre accompagnement.", "**Répondre aux signaux** de façon chaleureuse et régulière : bras, mots, consolation. L'enfant apprend qu'il peut compter sur nous."]}$kk$),
  (3,'reflexion',$kk${"question": "Pensez à un enfant que vous accompagnez. Quand s'éloigne-t-il de vous, et quand revient-il vers vous ?", "sous_titre": "Observer ces allers-retours aide à comprendre où il en est. Il n'y a pas de bonne réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer cette semaine", "titre": "Être un port d'attache visible", "etapes": [{"titre": "Me rendre visible.", "texte": "Je me place sur ma proposition de jeu pour être vu et facilement accessible, les yeux à hauteur des enfants."}, {"titre": "Accueillir chaque venue.", "texte": "Quand un enfant revient vers moi, je lui fais savoir que je suis là pour lui."}, {"titre": "Le laisser repartir.", "texte": "Je le console au besoin, puis je le laisse repartir quand il le souhaite."}], "note": "Choisissez un seul de ces gestes et testez-le toute la semaine."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 1 % 1/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 13.1b

-- ---------------------------------------------------------------------------
-- 13.2a Trame de la séquence 2/3 (Analyse d'une situation vécue). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Chaque enfant choisit ses figures d'attachement. L'équipe observe et s'organise pour qu'il en trouve.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de décrire qui sécurise quel enfant sur le site (sa constellation d'attachement) et de proposer ce que l'équipe peut faire pour qu'un enfant encore insécure trouve une base stable.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Développement du jeune enfant et besoins affectifs"}, "duree_min": 45, "materiel": ["Paperboard et feutres (pour dessiner une constellation, sans nom)", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Retour sur la semaine : chacun dit en une phrase ce qu'il a essayé de son engagement « Cette semaine, je… », sans l'évaluer.", "Demander qui apporte la situation d'un enfant à analyser."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Chaque enfant choisit ses figures d'attachement : l'équipe observe et s'organise pour qu'il en trouve.", "idees": ["L'attachement du jeune enfant est multiple : il s'attache à ses parents, à d'autres adultes, parfois à d'autres enfants. Les professionnels qui s'occupent régulièrement de lui sont d'autres étoiles de sa constellation d'attachement. Ce sont toujours les enfants qui choisissent.", "Si l'enfant est encore insécure : le professionnel qui l'accompagne depuis son premier accueil poursuit, ou l'équipe observe s'il choisit une autre personne (il s'endort mieux avec elle, se calme plus dans ses bras). S'il semble perdu, on nomme un ou des professionnels qui deviennent ses figures d'attachement, jusqu'à ce qu'il retrouve assez de sécurité pour jouer. Les parents sont associés et informés.", "L'enfant a d'autres moyens de se sécuriser : le pouce, la sucette, le doudou. Mais un doudou proposé systématiquement à tout chagrin finit par prendre la place de l'adulte, qui reste la figure d'attachement et le meilleur moyen de s'apaiser."], "support": "Projet pédagogique Koalakids, « De l'attachement à l'exploration »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Dessiner au paperboard la constellation d'un enfant du site, sans le nommer : qui le sécurise, auprès de qui se calme-t-il, avec qui joue-t-il ?", "questions": ["Que s'est-il passé ? (ce que l'on observe, sans interpréter)", "Quel besoin de l'enfant ? A-t-il au moins une base stable à la crèche ?", "Que peut faire l'équipe pour qu'il en trouve une, ou pour élargir sa constellation ?", "Que dit-on aux parents, et à quel moment ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : observer vers qui un enfant se tourne quand il est en difficulté.", "Exemple : au lieu de proposer le doudou en premier, m'approcher et consoler avec mes bras et mes mots.", "Exemple : dire à un parent qui l'enfant a choisi comme repère aujourd'hui."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 3/3 : retour d'expérience sur la pratique testée, avec un focus sur les arrivées et les départs."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 1 % 2/3 %';
-- FIN 13.2a

-- ---------------------------------------------------------------------------
-- 13.2b Blocs de la séquence 2/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "La constellation d'attachement", "paragraphes": ["Pour grandir, un enfant n'a pas besoin d'une seule personne : il a besoin de **plusieurs adultes disponibles**, qu'il choisit. Chacun est une étoile de sa constellation d'attachement.", "Notre rôle n'est pas de choisir à sa place. C'est d'observer vers qui il se tourne, et d'organiser la crèche pour qu'il trouve au moins une base stable."]}$kk$),
  (1,'scenes',$kk${"titre": "Trois situations que vous reconnaîtrez", "items": [{"lettre": "A", "titre": "Elle ne se calme que dans les bras d'une collègue", "texte": "Inès pleure en fin de matinée. Dans les bras de sa référente habituelle, rien n'y fait ; une autre professionnelle la prend et elle s'apaise.", "analyse": "c'est une information, pas un échec. On observe : l'enfant semble choisir une autre figure qui la sécurise plus. L'équipe en parle, en tient compte dans l'organisation et en informe les parents."}, {"lettre": "B", "titre": "Il reste collé et regarde partir chaque adulte", "texte": "Hugo ne quitte pas l'adulte du regard et ne joue que s'il peut le toucher. Dès qu'une collègue se lève, il pleure.", "analyse": "il cherche encore à se sécuriser. On instaure une stabilité affective : un ou deux adultes repères, disponibles, jusqu'à ce qu'il ait assez de sécurité pour jouer. On évite de multiplier les changements d'adulte."}, {"lettre": "C", "titre": "On lui tend le doudou dès qu'il est triste", "texte": "À chaque chagrin, Lina reçoit son doudou en premier. Elle le serre, mais elle cherche encore l'adulte du regard.", "analyse": "le doudou aide à supporter, mais proposé systématiquement il prend la place de l'adulte. L'adulte reste la figure d'attachement : on s'approche, on console par les bras et les mots, et le doudou vient en plus."}]}$kk$),
  (2,'comparaison',$kk${"intro": "Pour accompagner un enfant qui cherche encore à se sécuriser.", "plutot": ["Observer vers qui l'enfant se tourne et s'en servir dans l'organisation.", "Désigner un adulte stable et disponible lors des premiers accueils.", "Informer les parents et les associer aux décisions.", "Consoler par les bras et par les mots."], "eviter": ["Tarder à répondre à ses signaux.", "Lui imposer un adulte qu'il n'a pas choisi.", "Proposer systématiquement le doudou à la place de l'adulte.", "Changer souvent d'adulte autour de lui."]}$kk$),
  (3,'reflexion',$kk${"question": "Pour l'enfant que vous avez en tête, qui est dans sa constellation sur le site ? Y a-t-il quelqu'un qui manque ?", "sous_titre": "Il s'agit de décrire, pas de juger. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer pendant l'analyse", "titre": "Dessiner une constellation", "etapes": [{"titre": "L'enfant au centre.", "texte": "Sans le nommer, on le dessine au centre du paperboard."}, {"titre": "Les étoiles.", "texte": "On ajoute les adultes et les enfants auprès de qui il se calme, joue ou cherche du réconfort."}, {"titre": "Ce qui manque.", "texte": "On repère les moments de la journée où il n'a pas de repère et on décide d'un geste pour y répondre."}], "note": "On observe des relations, on ne juge personne."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 1 % 2/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 13.2b

-- ---------------------------------------------------------------------------
-- 13.3a Trame de la séquence 3/3 (Test d'une pratique et retour d'expérience). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Un accueil sûr se prépare : un adulte disponible, un jeu, des rituels qui appartiennent aux familles.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire ce qu'a changé la pratique testée au moment de la séparation ou des retrouvailles, et l'équipe a choisi une pratique commune pour des arrivées et des départs plus sûrs.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Développement du jeune enfant et besoins affectifs"}, "duree_min": 45, "materiel": ["Fiche de trace", "Engagements de la séance 2", "Paperboard"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Chacun relit son engagement de la séance 2 (« Cette semaine, je… »).", "Rappeler la règle : on raconte ce qu'on a fait, on ne se juge pas."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Un accueil sûr se prépare : un adulte disponible, un jeu, des rituels qui appartiennent aux familles.", "idees": ["Dès l'arrivée du premier enfant, au moins une proposition de jeu avec un adulte présent, stable et disponible : le jeu est un bon espace pour se séparer et se retrouver. L'adulte accueille parents et enfants par sa présence et ses paroles de bienvenue.", "Les rituels d'au revoir et de retrouvailles appartiennent aux familles : ce sont les parents, et parfois l'enfant, qui les choisissent. Notre rôle est de les soutenir et d'en parler en cas de difficulté. Un enfant qui ne veut pas venir ou partir n'est pas capricieux : il a besoin de plus de temps et de rituel.", "L'adulte peut faire confiance à l'enfant et soutenir son exploration sans le garder tout près, tant que l'environnement est sûr et qu'il est disponible : il accueille l'enfant à chacune de ses venues et le console pour qu'il reparte en son temps."], "support": "Projet pédagogique Koalakids, « De l'attachement à l'exploration »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site (retour d'expérience)", "consigne": "Chacun raconte en une minute la pratique qu'il a testée. On cherche ce qui s'est passé, pas qui a bien ou mal fait.", "questions": ["Qu'ai-je testé, et dans quelle situation ?", "Qu'a fait l'enfant au moment de la séparation ou des retrouvailles ? Qu'est-ce qui a changé, même un peu ?", "Qu'est-ce qui a été difficile ?", "Que gardons-nous en équipe ? Que changeons-nous ?"]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Choisir ensemble une pratique commune à tenir pendant deux semaines, puis un engagement par personne.", "amorce": "Cette semaine, je…", "consignes": ["Pratique commune : une phrase que chacun peut décrire de la même façon.", "Chacun s'engage sur un geste précis, noté sur la fiche de trace."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Tour de table : ce que je retiens du module 1. Annoncer le prochain module du programme et la date de la première séance."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 1 % 3/3 %';
-- FIN 13.3a

-- ---------------------------------------------------------------------------
-- 13.3b Blocs de la séquence 3/3. Attendu : 4 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Arrivées et départs", "paragraphes": ["Les arrivées et les départs sont les moments où l'attachement se joue le plus visiblement : on se sépare, on se retrouve. Ils comptent pour l'enfant, pour le parent, et pour nous.", "Cette dernière séance sert à regarder ensemble ce que vous avez testé, et à choisir **une pratique commune** pour que ces moments soient plus sûrs."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Un adulte stable et disponible sur un jeu** dès l'arrivée du premier enfant : le jeu aide à se séparer et à se retrouver.", "**Les rituels appartiennent aux familles :** nous les soutenons, nous ne les imposons pas.", "**Accueillir chaque venue** de l'enfant, le consoler au besoin, le laisser repartir en son temps."]}$kk$),
  (2,'reflexion',$kk${"question": "Dans quels moments de la journée vous sentez-vous le plus « port d'attache » pour les enfants ? Et le moins ?", "sous_titre": "Repérer ces moments aide l'équipe à se répartir. Il n'y a pas de bonne réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (3,'essayer',$kk${"label": "À essayer après la séance", "titre": "Un accueil plus sûr", "etapes": [{"titre": "Un adulte sur un jeu dès l'arrivée.", "texte": "Quelqu'un de stable et disponible est installé avant le premier enfant."}, {"titre": "Soutenir le rituel de la famille.", "texte": "Je laisse la famille faire à sa manière, sans l'initier à sa place."}, {"titre": "En reparler en équipe.", "texte": "À la prochaine réunion, quelques minutes pour dire ce qu'on garde."}], "note": "Toute pratique commune se décrit en une phrase."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 1 % 3/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 13.3b

-- ---------------------------------------------------------------------------
-- 13c Contrôle (lecture seule). Attendu : 3 séquences, blocs 5 / 5 / 4, publie = false.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame->>'objectif') is not null as objectif_ok,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs
from public.module m where m.titre like 'Module 1 %/3 %' order by m.ordre;
-- FIN 13c
